// Writes lib/api/schema.gen.ts from the API's /openapi.json, so a request or response model that changes
// shows in the web's types. `--check` fails when the committed file is stale (run by harness/init.sh).
// The spec comes from the FastAPI app in-process: no server, no database.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const web = path.join(import.meta.dirname, '..');
const target = path.join(web, 'lib/api/schema.gen.ts');
const HEADER =
  '// biome-ignore-all format: generated by lint/gen-api-types.mjs (pnpm api:types), do not edit\n' +
  '// Request and response models of the API, from its /openapi.json.\n';

// web/.pnpmfile.cjs gives openapi-typescript its own TypeScript 5; when that stops working, its
// compiler API errors look unrelated to the generator, so name the pin instead.
async function generateTypes(spec) {
  try {
    const { default: openapiTS, astToString } = await import('openapi-typescript');
    return astToString(await openapiTS(spec));
  } catch (error) {
    console.error(
      'openapi-typescript could not run: check web/.pnpmfile.cjs, which gives it TypeScript 5; see issue #601',
    );
    throw error;
  }
}

const spec = execFileSync(
  'uv',
  [
    'run',
    '--locked',
    '--quiet',
    'python',
    '-c',
    'import json; from app.main import app; print(json.dumps(app.openapi()))',
  ],
  { cwd: path.join(web, '..', 'api'), encoding: 'utf8', maxBuffer: 1 << 28 },
);
const generated = HEADER + (await generateTypes(JSON.parse(spec)));

if (process.argv.includes('--check')) {
  let committed = '';
  try {
    committed = readFileSync(target, 'utf8');
  } catch {}
  if (committed !== generated) {
    console.error(
      'web/lib/api/schema.gen.ts is out of date with the API models. Run `pnpm api:types` in web/ and commit it.',
    );
    process.exit(1);
  }
} else {
  writeFileSync(target, generated);
}
